// App icons served from embedded data (binary files can't go through GitHub's web editor). Generated by build.py.
const ICONS = {"apple-touch-icon.png": "", "icon-192.png": "", "icon-512.png": "", "maskable-512.png": ""};
export async function onRequestGet({ request, params }) {
  const name = params.icon; const b64 = ICONS[name];
  if (!b64) return new Response('Not found', { status: 404 });
  const cache = caches.default; const hit = await cache.match(request); if (hit) return hit;
  const bin = atob(b64); const bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const res = new Response(bytes, { headers: { 'content-type': 'image/png', 'cache-control': 'public, max-age=604800' } });
  await cache.put(request, res.clone()); return res;
}
